#!/usr/bin/env python3
"""Generates src/decoders/modern/aac/sauti_aac_twinvq_tables.c and include/sauti_aac_twinvq_tables.h: the DATA tables of the MPEG-4 TwinVQ base layer (AOT 7, ISO/IEC 14496-3 subpart 4):
the LSP codebook with the moving-average predictor (20b19s48bs), the two interleaved spectrum codebooks of long and short frames (cdmdct_0..3), the Bark envelope codebook (fcdl) and
the pitch codebook (pcdl).  Source: the ISO/IEC 14496-5 reference software (src_tf/ntt_get_cdbk.c, arrays tvqtab_*), read-only, outside the repository; the licence note of the reference
software is reproduced in licenses/ISO-MPEG4-AUDIO-REFSOFT.txt and in the generated header.  Only DATA is taken, the decoder is written for Sauti.
usage: tools/gen_twinvq_tables.py [path to ntt_get_cdbk.c]   (default ~/tmp_ayo/tmp/isovm/C050470e_Electronic_inserts/audio/natural/mp4AudVm_Rewrite/src_tf/ntt_get_cdbk.c)"""
import os, re, sys

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
SRC = os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '~/tmp_ayo/tmp/isovm/C050470e_Electronic_inserts/audio/natural/mp4AudVm_Rewrite/src_tf/ntt_get_cdbk.c')
# (name in the reference, new name, number of values, meaning)
TABLES = [
    ('tvqtab_20b19s48bs', 'sauti_twinvq_lsp', (64 + 16) * 20 + 2 * 20, 'LSP codebook: 64 first-stage and 16 second-stage vectors of 20 values, then the moving-average predictor coefficients of the 2 modes (2 x 20)'),
    ('tvqtab_cdmdct_0', 'sauti_twinvq_cb_long0', 32 * 20, 'spectrum shape codebook, long frames, conjugate channel 0: 32 vectors of 20'),
    ('tvqtab_cdmdct_1', 'sauti_twinvq_cb_long1', 32 * 20, 'spectrum shape codebook, long frames, conjugate channel 1: 32 vectors of 20'),
    ('tvqtab_cdmdct_2', 'sauti_twinvq_cb_short0', 32 * 17, 'spectrum shape codebook, short frames, conjugate channel 0: 32 vectors of 17'),
    ('tvqtab_cdmdct_3', 'sauti_twinvq_cb_short1', 32 * 17, 'spectrum shape codebook, short frames, conjugate channel 1: 32 vectors of 17'),
    ('tvqtab_fcdl', 'sauti_twinvq_cb_env', 64 * 6, 'Bark envelope codebook: 64 vectors of 6 (7 divisions of the 42 bands)'),
    ('tvqtab_pcdl', 'sauti_twinvq_cb_pitch', 128 * 10, 'pitch codebook: 2 x 64 vectors of 10'),
]
text = open(SRC).read()
NOTICE = ('/* This data was taken from the MPEG-4 Audio reference software (ISO/IEC 14496-5), file src_tf/ntt_get_cdbk.c.  Its licence note: "This software module was originally developed\n'
          ' * by NTT ... in the course of development of the MPEG-2 AAC/MPEG-4 Audio standard ISO/IEC 13818-7, 14496-1,2 and 3.  ISO/IEC gives users of the MPEG-2 AAC/MPEG-4 Audio standards\n'
          ' * free license to this software module or modifications thereof for use in hardware or software products claiming conformance to the MPEG-2 AAC/MPEG-4 Audio standards.  Those\n'
          ' * intending to use this software module in hardware or software products are advised that this use may infringe existing patents.  ...  Copyright is not released for non\n'
          ' * MPEG-2 AAC/MPEG-4 Audio conforming products.  This copyright notice must be included in all copies or derivative works."  Full text: licenses/ISO-MPEG4-AUDIO-REFSOFT.txt. */\n')
out_c = ['/* GENERATED by tools/gen_twinvq_tables.py - do not edit.  TwinVQ (MPEG-4 Audio object type 7) base layer data tables. */\n', NOTICE, '#include "sauti_aac_twinvq_tables.h"\n']
out_h = ['#ifndef SAUTI_AAC_TWINVQ_TABLES_H\n#define SAUTI_AAC_TWINVQ_TABLES_H\n/* GENERATED by tools/gen_twinvq_tables.py - do not edit.  TwinVQ base layer data tables (provenance below and in docs/POCHODZENIE_DANYCH.md). */\n', NOTICE]
for ref, name, n, doc in TABLES:
    m = re.search(r'double\s+' + ref + r'\s*\[\]\s*=\s*\{(.*?)\};', text, re.S)
    if not m: sys.exit('table %s not found' % ref)
    vals = re.findall(r'[-+]?\d+\.?\d*(?:[eE][-+]?\d+)?', m.group(1))
    if len(vals) != n: sys.exit('%s: %d values, expected %d' % (ref, len(vals), n))
    out_h.append('/* %s (from %s, %d values) */\nextern const double %s[%d];\n' % (doc, ref, n, name, n))
    rows = [', '.join(vals[i:i + 8]) for i in range(0, n, 8)]
    out_c.append('const double %s[%d] = {\n    %s\n};\n' % (name, n, ',\n    '.join(rows)))
out_h.append('#endif\n')
open(os.path.join(ROOT, 'src/decoders/modern/aac/sauti_aac_twinvq_tables.c'), 'w').write('\n'.join(out_c))
open(os.path.join(ROOT, 'include/sauti_aac_twinvq_tables.h'), 'w').write('\n'.join(out_h))
print('ok', sum(t[2] for t in TABLES), 'values')
